// =============================================================================
// AMARITI ROAS — Shopee Business Insights → Supabase
// Endpoints: /api/v2/product/get_item_list
//            /api/v2/analytics/get_shopee_business_insight
//
// ENV VARS obrigatórias (n8n → Settings → Environment Variables):
//   SHOPEE_PARTNER_ID       → ID numérico do parceiro
//   SHOPEE_PARTNER_KEY      → Chave HMAC do parceiro
//   SHOPEE_SHOP_ID_1        → ID numérico da loja Shopee
//   SHOPEE_ACCESS_TOKEN_1   → OAuth Access Token (renovar a cada 30 dias)
//
// ENV VARS para Supabase (usadas no nó HTTP Request seguinte):
//   SUPABASE_REST_URL       → ex: https://XXXXXX.supabase.co/rest/v1
//   SUPABASE_SERVICE_KEY    → Service Role Key (Supabase Dashboard → Settings → API)
// =============================================================================

const crypto = require('crypto');
const https  = require('https');

// ── Credenciais ────────────────────────────────────────────────────────────────
const PARTNER_ID   = String($env.SHOPEE_PARTNER_ID    || '').trim();
const PARTNER_KEY  = String($env.SHOPEE_PARTNER_KEY   || '').trim();
const SHOP_ID      = String($env.SHOPEE_SHOP_ID_1     || '').trim();
const ACCESS_TOKEN = String($env.SHOPEE_ACCESS_TOKEN_1 || '').trim();

if (!PARTNER_ID || !PARTNER_KEY || !SHOP_ID || !ACCESS_TOKEN) {
  throw new Error(
    'ENV Vars ausentes. Configure: SHOPEE_PARTNER_ID, SHOPEE_PARTNER_KEY, ' +
    'SHOPEE_SHOP_ID_1, SHOPEE_ACCESS_TOKEN_1'
  );
}

// ── Auth HMAC-SHA256 (Shopee Open Platform v2) ─────────────────────────────────
// Fórmula: HMAC(partner_key, partner_id + path + timestamp + access_token + shop_id)
function buildAuth(apiPath) {
  const ts   = Math.floor(Date.now() / 1000);
  const base = PARTNER_ID + apiPath + ts + ACCESS_TOKEN + SHOP_ID;
  const sign = crypto.createHmac('sha256', PARTNER_KEY).update(base).digest('hex');
  return { ts, sign };
}

// ── HTTP GET com HTTPS nativo (compatível com todos os ambientes n8n) ───────────
function shopeeGet(apiPath, extraParams) {
  return new Promise(function(resolve, reject) {
    const auth = buildAuth(apiPath);
    const qs   = new URLSearchParams(
      Object.assign(
        { partner_id: PARTNER_ID, shop_id: SHOP_ID,
          access_token: ACCESS_TOKEN, timestamp: String(auth.ts), sign: auth.sign },
        extraParams || {}
      )
    );
    const url = 'https://partner.shopeemobile.com' + apiPath + '?' + qs.toString();

    https.get(url, function(res) {
      var raw = '';
      res.on('data', function(c) { raw += c; });
      res.on('end', function() {
        try   { resolve(JSON.parse(raw)); }
        catch  { reject(new Error('JSON parse: ' + raw.slice(0, 300))); }
      });
    }).on('error', function(e) {
      reject(new Error('HTTPS error em ' + apiPath + ': ' + e.message));
    });
  });
}

// ── Janela de datas: últimos 30 dias ───────────────────────────────────────────
var now      = new Date();
var dateTo   = now.toISOString().slice(0, 10);
var dateFrom = new Date(+now - 30 * 86400 * 1000).toISOString().slice(0, 10);
var shopIdNum = parseInt(SHOP_ID, 10);
console.log('[shopee] Janela: ' + dateFrom + ' → ' + dateTo + ' | shop_id=' + shopIdNum);

// =============================================================================
// PASSO 1: Lista de produtos ativos (paginação automática)
// =============================================================================
var allItems = [];
var offset   = 0;
var hasNextPage = true;

while (hasNextPage) {
  var listRes = await shopeeGet('/api/v2/product/get_item_list', {
    offset:      String(offset),
    page_size:   '100',
    item_status: 'NORMAL',
  });

  if (listRes.error && listRes.error !== '') {
    throw new Error('[get_item_list] Erro ' + listRes.error + ': ' + listRes.message);
  }

  var batch = (listRes.response && listRes.response.item) ? listRes.response.item : [];
  allItems = allItems.concat(batch);

  hasNextPage = (listRes.response && listRes.response.has_next_page === true)
                || batch.length === 100;
  offset += 100;

  if (offset > 2000) {
    console.warn('[shopee] Limite de 2000 itens atingido na paginação de produtos');
    break;
  }
}

console.log('[shopee] ' + allItems.length + ' produtos ativos');

// Mapa item_id → { name, price, sku }
var itemMap = {};
allItems.forEach(function(i) {
  itemMap[i.item_id] = {
    name:  i.item_name || '',
    price: (i.price_info && i.price_info[0]) ? i.price_info[0].current_price : 0,
    sku:   i.item_sku  || String(i.item_id),
  };
});

// =============================================================================
// PASSO 2: Business Insights — organic_views, pedidos, receita (paginação)
// =============================================================================
var allInsights = [];
var pageNo      = 0;
var hasMoreInsights = true;

while (hasMoreInsights) {
  var insightRes = await shopeeGet('/api/v2/analytics/get_shopee_business_insight', {
    date_from: dateFrom,
    date_to:   dateTo,
    page_size: '100',
    page_no:   String(pageNo),
  });

  if (insightRes.error && insightRes.error !== '') {
    // 'error_not_found' = sem dados para o período → trata como lista vazia
    if (insightRes.error === 'error_not_found' || insightRes.error === 'error_param') {
      console.warn('[shopee] Business insights vazio: ' + insightRes.message);
      break;
    }
    throw new Error('[get_business_insight] Erro ' + insightRes.error + ': ' + insightRes.message);
  }

  var batchI = (insightRes.response && insightRes.response.business_insight)
                ? insightRes.response.business_insight
                : [];
  allInsights = allInsights.concat(batchI);

  hasMoreInsights = batchI.length === 100;
  pageNo++;

  if (pageNo > 20) {
    console.warn('[shopee] Limite de 2000 registros de insights atingido');
    break;
  }
}

console.log('[shopee] ' + allInsights.length + ' registros de business insight');

// =============================================================================
// PASSO 3: Transforma para schema roas.shopee_performance_data
// Colunas CRM (crm_status, cover_change_count, last_optimized_at) são
// AUSENTES do payload → preservadas em UPDATE, defaults aplicados em INSERT
// =============================================================================
var rows = allInsights
  .map(function(row) {
    var base     = itemMap[row.item_id] || { name: '', price: 0, sku: String(row.item_id) };
    var visitors = Number(row.uv          || 0);
    var orders   = Number(row.order_count || 0);

    return {
      shop_id:             shopIdNum,
      sku:                 String(base.sku).trim(),
      product_name:        String(row.item_name || base.name).slice(0, 255),
      organic_views:       Number(row.exposure_count || 0),
      organic_conversions: orders,
      revenue:             Number(row.gmv || 0),
      conversion_rate:     visitors > 0
                             ? parseFloat(((orders / visitors) * 100).toFixed(4))
                             : 0,
      ads_spend:           0,
      ads_conversions:     0,
      roas_score:          0,
      updated_at:          now.toISOString(),
    };
  })
  .filter(function(r) { return r.sku !== ''; });

console.log('[shopee] ' + rows.length + ' linhas prontas para upsert');

if (rows.length === 0) {
  console.warn('[shopee] Nenhuma linha para upsert — verificar datas ou configurações de loja');
}

// Retorna como item único; o nó HTTP Request fará 1 POST com o array completo
return [{ json: { rows: rows, meta: { count: rows.length, dateFrom: dateFrom, dateTo: dateTo } } }];
